import { mkdtempSync, rmSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";
import { App, createApp } from "../src/app";
import { eq, onCleanup, run, test } from "./harness";

interface Report {
  runId: number;
  batch: number;
  planned: number;
  published: number;
  delivered: number;
  failed: number;
  skippedOptOut: number;
  lines: { orderNo: string; customerId: string; kind: string; status: string; to: string }[];
  text: string;
}

interface CustomerAlerts {
  customerId: string;
  delivered: { orderNo: string; kind: string }[];
  inbox: string[];
}

/** 빈 스풀 디렉토리를 가진 앱 하나 */
function world() {
  const spoolDir = mkdtempSync(join(tmpdir(), "alerts-"));
  onCleanup(() => rmSync(spoolDir, { recursive: true, force: true }));
  const app: App = createApp({ spoolDir, mqpubBin: join(process.cwd(), "vendor", "bin", "mqpub") });

  const call = (method: string, url: string, body?: unknown): unknown => {
    const r = app.handle(method, url, body);
    eq(r.status, 200, `${method} ${url} → ${JSON.stringify(r.body)}`);
    return r.body;
  };

  return {
    app,
    spoolDir,
    customer(id: string, name: string, phone: string, smsOptIn = true): void {
      call("POST", "/customers", { id, name, phone, smsOptIn });
    },
    order(customerId: string, placedOn: string, channel: "direct" | "market" = "direct", partner?: string): string {
      return (call("POST", "/orders", { customerId, placedOn, channel, partner }) as { orderNo: string }).orderNo;
    },
    event(orderNo: string, kind: string): void {
      call("POST", `/orders/${encodeURIComponent(orderNo)}/events`, { kind });
    },
    dispatch(): Report {
      return call("POST", "/dispatch") as Report;
    },
    report(runId: number): Report {
      return call("GET", `/reports/dispatch/${runId}`) as Report;
    },
    alerts(customerId: string): CustomerAlerts {
      return call("GET", `/customers/${customerId}/alerts`) as CustomerAlerts;
    },
  };
}

test("every customer whose order shipped today gets a shipping text", () => {
  const w = world();
  const shoppers: [string, string, string][] = [
    ["C1001", "김하늘", "010-2000-1001"],
    ["C1002", "이도윤", "010-2000-1002"],
    ["C1003", "박서연", "010-2000-1003"],
    ["C1004", "최민준", "+82 10-2000-1004"],
    ["C1005", "정지우", "010 2000 1005"],
    ["C1006", "강예린", "010-2000-1006"],
    ["C1007", "윤시우", "010-2000-1007"],
  ];
  for (const [id, name, phone] of shoppers) w.customer(id, name, phone);

  const orders = [
    w.order("C1001", "2026-10-07"),
    w.order("C1002", "2026-10-07"),
    w.order("C1003", "2026-10-07"),
    w.order("C1004", "2026-10-08"),
    w.order("C1005", "2026-10-08", "market", "GMKT"),
    w.order("C1006", "2026-10-08", "market", "GMKT"),
    w.order("C1007", "2026-10-08", "market", "ELVN"),
  ];
  for (const o of orders) w.event(o, "SHIPPED");

  const report = w.dispatch();
  eq(report.planned, 7, "planned alerts");
  eq(report.lines.filter((l) => l.status !== "발송").map((l) => l.orderNo), [], "alerts not sent");
  eq(report.delivered, 7, "sent count on the dispatch report");

  for (const [id] of shoppers) {
    const a = w.alerts(id);
    eq(a.inbox.length, 1, `texts received by ${id}`);
    eq(a.inbox[0].includes("출발"), true, `shipping wording for ${id}`);
  }
});

test("opted-out customers are not texted and are counted separately", () => {
  const w = world();
  w.customer("C2001", "한지민", "010-3000-2001");
  w.customer("C2002", "오세훈", "010-3000-2002", false);
  w.event(w.order("C2001", "2026-10-09"), "PAID");
  w.event(w.order("C2002", "2026-10-09"), "PAID");
  const report = w.dispatch();
  eq(report.skippedOptOut, 1, "opted out");
  eq(report.delivered, 1, "sent");
  eq(w.alerts("C2002").inbox, [], "no text for opted-out");
});

test("each dispatch run goes out as one batch and nothing is sent twice", () => {
  const w = world();
  w.customer("C3001", "서지호", "010-4000-3001");
  const o = w.order("C3001", "2026-10-09");
  w.event(o, "PAID");
  const r1 = w.dispatch();
  w.event(o, "SHIPPED");
  const r2 = w.dispatch();
  const r3 = w.dispatch();
  eq([r1.batch, r2.batch], [1, 2], "batch per run");
  eq(r3.planned, 0, "nothing new");
  eq(w.alerts("C3001").inbox.length, 2, "two texts total");
  eq(w.report(1).delivered, 1, "stored report for run 1");
});

run();
type Fn = () => void | Promise<void>;
const registered: [string, Fn][] = [];
const cleanups: (() => void)[] = [];

export function test(name: string, fn: Fn): void {
  registered.push([name, fn]);
}

export function onCleanup(fn: () => void): void {
  cleanups.push(fn);
}

export function eq(actual: unknown, expected: unknown, label: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
}

export async function run(): Promise<void> {
  let failed = 0;
  for (const [name, fn] of registered) {
    try {
      await fn();
      console.log(`ok   - ${name}`);
    } catch (e) {
      failed++;
      console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }
  for (const c of cleanups) {
    try { c(); } catch { /* ignore */ }
  }
  console.log(failed === 0 ? "all passed" : `${failed} failed`);
  process.exitCode = failed === 0 ? 0 : 1;
}
import { CustomerRepository } from "../src/repository/customerRepository";
import { OrderRepository } from "../src/repository/orderRepository";
import { planNotifications } from "../src/service/notificationPlanner";
import { eq, run, test } from "./harness";

function setup() {
  const customers = new CustomerRepository();
  customers.save({ id: "C1", name: "가", phone: "010-1111-0001", smsOptIn: true });
  customers.save({ id: "C2", name: "나", phone: "010-1111-0002", smsOptIn: false });
  const orders = new OrderRepository();
  return { customers, orders };
}

test("repeated identical events in one run produce one alert", () => {
  const { customers, orders } = setup();
  const o = orders.create("C1", "direct", "2026-10-09");
  orders.addEvent(o.orderNo, "SHIPPED");
  orders.addEvent(o.orderNo, "SHIPPED");
  orders.addEvent(o.orderNo, "DELIVERED");
  const plan = planNotifications(orders.takePending(), customers);
  eq(plan.notifications.map((n) => n.kind), ["SHIPPED", "DELIVERED"], "kinds");
});

test("opt-out customers are skipped and counted", () => {
  const { customers, orders } = setup();
  orders.addEvent(orders.create("C2", "direct", "2026-10-09").orderNo, "PAID");
  orders.addEvent(orders.create("C1", "direct", "2026-10-09").orderNo, "PAID");
  const plan = planNotifications(orders.takePending(), customers);
  eq(plan.skippedOptOut, 1, "skipped");
  eq(plan.notifications.map((n) => n.customerId), ["C1"], "kept");
});

test("pending events are taken once, in recorded order", () => {
  const { orders } = setup();
  const a = orders.create("C1", "direct", "2026-10-09").orderNo;
  const b = orders.create("C1", "market", "2026-10-09", "ELVN").orderNo;
  orders.addEvent(b, "PAID");
  orders.addEvent(a, "PAID");
  eq(orders.takePending().map((e) => e.orderNo), [b, a], "order");
  eq(orders.takePending(), [], "second take");
});

run();
import { formatOrderNo } from "../src/domain/order";
import { decodePayload, encodePayload } from "../src/messaging/payloadCodec";
import { renderAlert } from "../src/notifier/templates";
import { clip, displayWidth, maskMobile, normalizeMobile } from "../src/util/format";
import { eq, run, test } from "./harness";

test("mobile numbers normalize to 11 digits", () => {
  eq(normalizeMobile("010-1234-5678"), "01012345678", "dashes");
  eq(normalizeMobile("+82 10 1234 5678"), "01012345678", "country code");
  eq(normalizeMobile("8201012345678"), null, "country code with trunk zero is rejected");
  eq(normalizeMobile("011-123-4567"), "01101234567", "old 10-digit");
  eq(normalizeMobile("02-123-4567"), null, "landline");
  eq(maskMobile("01012345678"), "010-****-5678", "mask");
});

test("order numbers follow the channel format", () => {
  eq(formatOrderNo("direct", "2026-10-07", 42), "O261007-00042", "direct");
  eq(formatOrderNo("market", "2026-10-07", 123, "GMKT"), "M-GMKT-261007-000123", "market");
});

test("payload round-trips and strips control characters", () => {
  const raw = encodePayload({ orderNo: "O261007-00042\t", customerId: "C1001", kind: "SHIPPED" });
  eq(raw.includes("\t"), false, "no tab on the wire");
  eq(decodePayload(raw), { orderNo: "O261007-00042", customerId: "C1001", kind: "SHIPPED" }, "decode");
  eq(decodePayload("{"), null, "garbage");
  eq(decodePayload('{"v":9,"o":"x","c":"y","k":"PAID"}'), null, "unknown version");
});

test("alert text fits the sms width", () => {
  const t = renderAlert("DELIVERED", "김하늘", "M-GMKT-261007-000123");
  eq(displayWidth(t) <= 80, true, "width");
  eq(clip("가나다라", 5), "가나…", "clip");
});

run();

